-- PortoEX Dados Operacionais · Supabase (projeto do Veículos Voltando Vazios)
-- Rode tudo de uma vez no SQL Editor do Supabase.
-- =====================================================================

-- 1) Renomeia a tabela do Veículos Voltando Vazios para deixar claro o que é de quem.
--    (As permissões/policies que já existem acompanham a tabela automaticamente.)
--    ATENÇÃO: depois de rodar, suba a nova versão do site (pasta vazios/),
--    porque a versão antiga ainda procura a tabela "registros".
alter table if exists public.registros rename to veiculos_vazios;

-- 2) Tabela nova das Coletas Improdutivas
create table if not exists public.coletas_improdutivas (
  id          bigint generated by default as identity primary key,
  data        date not null,
  motorista   text not null,
  placa       text not null,
  chegada     time not null,
  saida       time not null,
  cliente     text not null,
  cidade      text not null,
  servico     text not null,
  causa       text not null,
  obs         text,
  criado_em   timestamptz not null default now(),
  criado_por  uuid default auth.uid()
);

-- 3) Segurança: só quem faz login no site consegue ver, lançar e excluir
alter table public.coletas_improdutivas enable row level security;

drop policy if exists "coletas - ler (logado)"     on public.coletas_improdutivas;
drop policy if exists "coletas - lançar (logado)"  on public.coletas_improdutivas;
drop policy if exists "coletas - editar (logado)"  on public.coletas_improdutivas;
drop policy if exists "coletas - excluir (logado)" on public.coletas_improdutivas;

create policy "coletas - ler (logado)"     on public.coletas_improdutivas for select to authenticated using (true);
create policy "coletas - lançar (logado)"  on public.coletas_improdutivas for insert to authenticated with check (true);
create policy "coletas - editar (logado)"  on public.coletas_improdutivas for update to authenticated using (true) with check (true);
create policy "coletas - excluir (logado)" on public.coletas_improdutivas for delete to authenticated using (true);

